package cost

import (
	"math"
	"strings"

	"github.com/google/cel-go/checker"
	"github.com/google/cel-go/common/types"
	apiservercel "k8s.io/apiserver/pkg/cel"
)

// DeclTypeCostEstimator implements cel-go's checker.CostEstimator by walking the DeclType tree
// generated by apiservercel, extended with SizeBound and origin tracking.
type DeclTypeCostEstimator struct {
	rootTypes    map[string]*apiservercel.DeclType
	policyBounds bool
}

// NewDeclTypeCostEstimator creates a size and cost estimator backed by the registered DeclTypes.
func NewDeclTypeCostEstimator(roots map[string]*apiservercel.DeclType) *DeclTypeCostEstimator {
	return &DeclTypeCostEstimator{
		rootTypes:    roots,
		policyBounds: true, // Default to true for backward compatibility with existing tests
	}
}

// WithRootType returns a shallow copy of DeclTypeCostEstimator with an additional or overridden root type.
func (e *DeclTypeCostEstimator) WithRootType(name string, t *apiservercel.DeclType) *DeclTypeCostEstimator {
	newRoots := make(map[string]*apiservercel.DeclType, len(e.rootTypes)+1)
	for k, v := range e.rootTypes {
		newRoots[k] = v
	}
	newRoots[name] = t
	return &DeclTypeCostEstimator{
		rootTypes:    newRoots,
		policyBounds: e.policyBounds,
	}
}

// EstimateSize estimates the size of a collection or string node by walking the DeclType hierarchy.
func (e *DeclTypeCostEstimator) EstimateSize(element checker.AstNode) *checker.SizeEstimate {
	if element == nil {
		return nil
	}

	path := element.Path()
	if len(path) == 0 {
		if element.Type() == types.StringType {
			return &checker.SizeEstimate{Min: 0, Max: 253}
		}
		return nil
	}

	rootName := path[0]
	rootNode, ok := e.rootTypes[rootName]
	if !ok || rootNode == nil {
		if element.Type() == types.StringType {
			return &checker.SizeEstimate{Min: 0, Max: 253}
		}
		return nil
	}

	// Check platform policy bounds table first
	fullPathStr := strings.Join(path, ".")
	if bound, exists := PlatformPolicyBounds[fullPathStr]; exists {
		if bound.State == StateKnown || (e.policyBounds && bound.Origin == OriginPolicy) {
			return &checker.SizeEstimate{Min: 0, Max: bound.Max}
		}
	}

	currentNode := rootNode
	for _, name := range path[1:] {
		if currentNode == nil {
			return nil
		}

		switch name {
		case "@items", "@values":
			if currentNode.ElemType == nil {
				return nil
			}
			currentNode = currentNode.ElemType
		case "@keys", "@indices":
			if currentNode.KeyType == nil {
				return nil
			}
			currentNode = currentNode.KeyType
		default:
			field, ok := currentNode.Fields[name]
			if !ok || field.Type == nil {
				return nil
			}
			currentNode = field.Type
		}
	}

	if currentNode == nil {
		return nil
	}

	if currentNode.MaxElements > 0 {
		return &checker.SizeEstimate{Min: 0, Max: uint64(currentNode.MaxElements)}
	}

	if currentNode == apiservercel.StringType {
		return &checker.SizeEstimate{Min: 0, Max: 253}
	}

	return nil
}

// EstimateCallCost calculates static cost for built-in and OpenChoreo custom functions (oc_*).
func (e *DeclTypeCostEstimator) EstimateCallCost(function, overloadID string, target *checker.AstNode, args []checker.AstNode) *checker.CallEstimate {
	switch function {
	case "oc_hash":
		maxBytes := uint64(1024)
		if len(args) > 0 && args[0].ComputedSize() != nil {
			maxBytes = args[0].ComputedSize().Max
		}
		// Cost: 1 + ceil(0.1 * bytes)
		ceilCost := uint64(math.Ceil(float64(maxBytes) * 0.1))
		return &checker.CallEstimate{
			CostEstimate: checker.CostEstimate{
				Min: 1,
				Max: 1 + ceilCost,
			},
			ResultSize: &checker.SizeEstimate{Min: 8, Max: 8},
		}

	case "oc_generate_name", "oc_dns_label":
		maxBytes := uint64(1024)
		if len(args) > 0 && args[0].ComputedSize() != nil {
			maxBytes = args[0].ComputedSize().Max
		}
		ceilCost := uint64(math.Ceil(float64(maxBytes) * 0.1))
		maxResult := uint64(253)
		if function == "oc_dns_label" {
			maxResult = 63
		}
		if maxBytes < maxResult {
			maxResult = maxBytes
		}
		return &checker.CallEstimate{
			CostEstimate: checker.CostEstimate{
				Min: 1,
				Max: 1 + maxBytes + ceilCost,
			},
			ResultSize: &checker.SizeEstimate{Min: 0, Max: maxResult},
		}

	case "oc_merge":
		p1, p2 := uint64(50), uint64(50)
		if len(args) > 0 && args[0].ComputedSize() != nil {
			p1 = args[0].ComputedSize().Max
		}
		if len(args) > 1 && args[1].ComputedSize() != nil {
			p2 = args[1].ComputedSize().Max
		}
		return &checker.CallEstimate{
			CostEstimate: checker.CostEstimate{
				Min: 1,
				Max: 1 + p1 + p2,
			},
			ResultSize: &checker.SizeEstimate{Min: 0, Max: p1 + p2},
		}

	case "oc_omit":
		return &checker.CallEstimate{
			CostEstimate: checker.CostEstimate{
				Min: 1,
				Max: 1,
			},
			ResultSize: &checker.SizeEstimate{Min: 0, Max: 0},
		}

	case "distinct":
		if target == nil || (*target).ComputedSize() == nil {
			return nil
		}
		targetSz := (*target).ComputedSize().Max
		return &checker.CallEstimate{
			CostEstimate: checker.CostEstimate{
				Min: 1,
				Max: 1 + targetSz,
			},
			ResultSize: &checker.SizeEstimate{Min: 0, Max: targetSz},
		}

	case "flatten":
		// When flatten operates on a comprehension result whose intermediate container size
		// cannot be statically deduced by cel-go, cel-go undercounts (e.g. charging 1 instead of N + 11).
		// Per §4.3 and §1.1 Invariants ("Soundness over coverage: never add arbitrary margins; unmodeled
		// or undercounting node kinds evaluate as UNKNOWN"):
		if target == nil || (*target).ComputedSize() == nil {
			return &checker.CallEstimate{
				CostEstimate: checker.CostEstimate{
					Min: 1,
					Max: math.MaxUint64,
				},
				ResultSize: &checker.SizeEstimate{Min: 0, Max: math.MaxUint64},
			}
		}
		targetSz := (*target).ComputedSize().Max
		return &checker.CallEstimate{
			CostEstimate: checker.CostEstimate{
				Min: 1,
				Max: 11 + targetSz,
			},
			ResultSize: &checker.SizeEstimate{Min: 0, Max: targetSz},
		}
	}

	return nil
}

var _ checker.CostEstimator = &DeclTypeCostEstimator{}
